
const WORDS=[{"id": 0, "w": "玉", "p": "yù", "t": "名词", "m": "ngọc, ngọc thạch", "coll": "一块玉、玉器", "s": "这块玉质地细腻经过打磨以后显得更加温润。"}, {"id": 1, "w": "答复", "p": "dáfù", "t": "动词", "m": "trả lời", "coll": "及时答复、明确答复", "s": "收到对方的询问以后，她认真核实情况及时作出了答复。"}, {"id": 2, "w": "得罪", "p": "dézui", "t": "动词", "m": "làm mất lòng, xúc phạm", "coll": "得罪别人、无意中得罪", "s": "他担心自己的话会得罪别人于是先说明了提出建议的原因。"}, {"id": 3, "w": "大臣", "p": "dàchén", "t": "名词", "m": "đại thần", "coll": "一位大臣、大臣进言", "s": "故事中的大臣向国王进言希望他重新考虑这个决定。"}, {"id": 4, "w": "对策", "p": "duìcè", "t": "名词", "m": "đối sách, biện pháp đối phó", "coll": "制定对策、商量对策", "s": "发现问题以后，团队立即商量对策尽量减少对后续工作的影响。"}, {"id": 5, "w": "提议", "p": "tíyì", "t": "动词", "m": "đề nghị, đề xuất", "coll": "提出提议、接受提议", "s": "他提议先核实资料再根据实际情况决定下一步的安排。"}, {"id": 6, "w": "请教", "p": "qǐngjiào", "t": "动词", "m": "xin chỉ bảo, hỏi ý kiến", "coll": "向老师请教、虚心请教", "s": "遇到不理解的问题，她会主动向老师请教而不是随意猜测。"}, {"id": 7, "w": "实力", "p": "shílì", "t": "名词", "m": "thực lực, sức mạnh", "coll": "增强实力、实力雄厚", "s": "这支队伍通过长期训练不断增强实力在比赛中取得了进步。"}, {"id": 8, "w": "慷慨", "p": "kāngkǎi", "t": "形容词", "m": "rộng rãi, hào phóng", "coll": "慷慨解囊、十分慷慨", "s": "这位老人十分慷慨常常拿出自己的积蓄帮助有需要的人。"}, {"id": 9, "w": "亏待", "p": "kuīdài", "t": "动词", "m": "xử tệ, đối đãi kém", "coll": "不曾亏待、亏待别人", "s": "这些年来，他从未亏待合作伙伴始终按照约定支付报酬。"}, {"id": 10, "w": "动身", "p": "dòngshēn", "t": "动词", "m": "lên đường, khởi hành", "coll": "准备动身、动身前往", "s": "确认车票以后，他们准备动身前往下一座城市。"}, {"id": 11, "w": "磋商", "p": "cuōshāng", "t": "动词", "m": "bàn bạc, trao đổi", "coll": "双方磋商、进行磋商", "s": "双方经过多轮磋商终于就合作方式达成了一致。"}, {"id": 12, "w": "荣幸", "p": "róngxìng", "t": "形容词", "m": "vinh dự", "coll": "深感荣幸、十分荣幸", "s": "能够参与这次交流活动她深感荣幸也认真做好了准备。"}, {"id": 13, "w": "转达", "p": "zhuǎndá", "t": "动词", "m": "truyền đạt, chuyển", "coll": "转达问候、转达意见", "s": "请你替我转达问候并告诉老师我们都很想念他。"}, {"id": 14, "w": "爱不释手", "p": "àibùshìshǒu", "t": "成语", "m": "thích quá nên cầm mãi không chịu buông", "coll": "爱不释手、令人爱不释手", "s": "这本书图文精美孩子一拿到手便爱不释手。"}, {"id": 15, "w": "圈套", "p": "quāntào", "t": "名词", "m": "cái bẫy, mưu kế lừa gạt", "coll": "设下圈套、落入圈套", "s": "故事中的人物没有核实对方的身份结果落入了事先设好的圈套。"}, {"id": 16, "w": "归还", "p": "guīhuán", "t": "动词", "m": "trả lại, trả về", "coll": "归还物品、按时归还", "s": "借用这些资料以后，请按照约定的时间及时归还。"}, {"id": 17, "w": "从容", "p": "cóngróng", "t": "形容词", "m": "ung dung, điềm tĩnh", "coll": "从容应对、神情从容", "s": "面对突然提出的问题，她仍然从容应对清楚地说明了自己的观点。"}, {"id": 18, "w": "中央", "p": "zhōngyāng", "t": "名词", "m": "giữa, trung tâm", "coll": "大厅中央、道路中央", "s": "大厅中央摆放着一张长桌上面陈列着这次展览的介绍资料。"}, {"id": 19, "w": "兑现", "p": "duìxiàn", "t": "动词", "m": "thực hiện, hoàn thành", "coll": "兑现承诺、按时兑现", "s": "作出承诺以后，就应该认真兑现而不能只停留在口头上。"}, {"id": 20, "w": "妄想", "p": "wàngxiǎng", "t": "动词", "m": "ảo tưởng, mơ ước vẩn vơ", "coll": "心存妄想、不切实际的妄想", "s": "如果只等待机会却不愿付出努力所谓的计划可能只是一种妄想。"}, {"id": 21, "w": "发誓", "p": "fāshì", "t": "动词", "m": "thề, tuyên thệ", "coll": "发誓改正、郑重发誓", "s": "他发誓要改正自己的错误但大家更希望看到实际行动。"}, {"id": 22, "w": "尸体", "p": "shītǐ", "t": "名词", "m": "thi thể, xác chết", "coll": "发现尸体、辨认尸体", "s": "这部侦探小说从河边发现一具尸体开始逐步展开对事件真相的调查。"}, {"id": 23, "w": "撒谎", "p": "sāhuǎng", "t": "动词", "m": "nói dối", "coll": "不能撒谎、撒谎骗人", "s": "做错事情以后，不应该撒谎掩盖，而应该诚实说明情况并承担责任。"}, {"id": 24, "w": "隆重", "p": "lóngzhòng", "t": "形容词", "m": "long trọng, linh đình", "coll": "隆重举行、场面隆重", "s": "庆祝活动在广场上隆重举行许多居民都前来参加。"}, {"id": 25, "w": "仪式", "p": "yíshì", "t": "名词", "m": "nghi thức, nghi lễ", "coll": "开幕仪式、举行仪式", "s": "开幕仪式结束以后，来宾们依次进入展厅参观本次展出的作品。"}, {"id": 26, "w": "沐浴", "p": "mùyù", "t": "动词", "m": "tắm gội", "coll": "沐浴阳光、沐浴更衣", "s": "清晨，院子里的花草沐浴着阳光叶片上还留着细小的水珠。"}, {"id": 27, "w": "荤", "p": "hūn", "t": "名词", "m": "món mặn (thịt hoặc cá)", "coll": "荤素搭配、荤菜", "s": "这家餐厅既提供荤菜也准备了素食方便不同需求的客人选择。"}, {"id": 28, "w": "庄严", "p": "zhuāngyán", "t": "形容词", "m": "trang nghiêm", "coll": "庄严的气氛、神情庄严", "s": "纪念仪式上，人们神情庄严安静地听着主持人的介绍。"}, {"id": 29, "w": "无理取闹", "p": "wúlǐ qǔnào", "t": "成语", "m": "cố tình gây sự, kiếm chuyện vô cớ", "coll": "无理取闹、停止无理取闹", "s": "工作人员已经解释清楚规则对方，却仍然无理取闹。"}, {"id": 30, "w": "冒犯", "p": "màofàn", "t": "动词", "m": "xúc phạm", "coll": "无意冒犯、冒犯他人", "s": "讨论不同习俗时，应当注意表达方式避免因为不了解而冒犯他人。"}, {"id": 31, "w": "亦", "p": "yì", "t": "副词", "m": "cũng", "coll": "人云亦云、亦有不同", "s": "面对未经证实的说法，我们，不应人云亦云，而要先核实事实。"}, {"id": 32, "w": "边境", "p": "biānjìng", "t": "名词", "m": "biên giới", "coll": "边境地区、越过边境", "s": "这本游记记录了作者在边境地区走访不同村庄的见闻。"}, {"id": 33, "w": "泄露", "p": "xièlòu", "t": "动词", "m": "tiết lộ, để lộ", "coll": "泄露消息、泄露隐私", "s": "分享照片以前，请先检查内容避免无意中泄露他人的隐私。"}, {"id": 34, "w": "率领", "p": "shuàilǐng", "t": "动词", "m": "dẫn đầu", "coll": "率领队伍、率领团队", "s": "她率领团队经过反复试验终于解决了关键问题。"}, {"id": 35, "w": "镇静", "p": "zhènjìng", "t": "形容词", "m": "bình tĩnh, điềm tĩnh", "coll": "保持镇静、神情镇静", "s": "面对突发情况，负责人保持镇静有条不紊地安排相关工作。"}, {"id": 36, "w": "雄厚", "p": "xiónghòu", "t": "形容词", "m": "hùng hậu", "coll": "实力雄厚、资金雄厚", "s": "这家机构不仅资金雄厚也十分重视专业人才的培养。"}, {"id": 37, "w": "一贯", "p": "yīguàn", "t": "形容词／副词", "m": "trước sau như một, xưa nay vẫn", "coll": "一贯如此、一贯认真", "s": "他做事一贯认真即使是很小的细节也会仔细核对。"}, {"id": 38, "w": "霸道", "p": "bàdào", "t": "形容词", "m": "độc đoán, chuyên chế", "coll": "态度霸道、行为霸道", "s": "他不再用霸道的态度要求别人接受意见，而是学会了耐心倾听。"}, {"id": 39, "w": "声誉", "p": "shēngyù", "t": "名词", "m": "danh tiếng, tiếng tăm", "coll": "良好声誉、维护声誉", "s": "这家老店凭借可靠的品质在顾客中赢得了良好的声誉。"}, {"id": 40, "w": "列举", "p": "lièjǔ", "t": "动词", "m": "liệt kê, nêu ra", "coll": "列举事例、逐一列举", "s": "为了说明自己的观点，她列举了几个事例并解释其中的联系。"}, {"id": 41, "w": "履行", "p": "lǚxíng", "t": "动词", "m": "thực hiện, thực thi", "coll": "履行职责、履行承诺", "s": "接受这项工作，就意味着需要认真履行职责不能随意推卸责任。"}, {"id": 42, "w": "歪曲", "p": "wāiqū", "t": "动词", "m": "xuyên tạc, bóp méo", "coll": "歪曲事实、歪曲原意", "s": "转述别人的观点时，应该尊重原意不要为了支持自己而歪曲事实。"}, {"id": 43, "w": "理直气壮", "p": "lǐzhí qìzhuàng", "t": "成语", "m": "có lý lẽ chính đáng nên tự tin, dõng dạc", "coll": "理直气壮、理直气壮地说明", "s": "他掌握了充分的证据，因此能够理直气壮地说明自己的理由。"}, {"id": 44, "w": "压迫", "p": "yāpò", "t": "动词", "m": "áp bức, đè ép", "coll": "反抗压迫、受到压迫", "s": "这部作品描写了普通人面对压迫时坚持争取尊严的经历。"}, {"id": 45, "w": "口头", "p": "kǒutóu", "t": "形容词", "m": "bằng lời nói, ngoài miệng", "coll": "口头说明、口头承诺", "s": "除了口头说明，工作人员还提供了文字材料方便大家随时查阅。"}, {"id": 46, "w": "副", "p": "fù", "t": "量词", "m": "gương, bộ (mặt), cặp, đôi", "coll": "一副眼镜、一副手套", "s": "出门以前，他从桌上拿起一副眼镜小心地放进包里。"}, {"id": 47, "w": "姿态", "p": "zītài", "t": "名词", "m": "dáng dấp, thái độ, dáng vẻ", "coll": "优美的姿态、合作姿态", "s": "双方都表现出愿意合作的姿态希望通过交流解决分歧。"}, {"id": 48, "w": "隔阂", "p": "géhé", "t": "名词", "m": "sự ngăn cách, bất hòa, thiếu thấu hiểu", "coll": "消除隔阂、产生隔阂", "s": "真诚的交流能够帮助人们逐渐消除隔阂增进彼此的理解。"}, {"id": 49, "w": "争端", "p": "zhēngduān", "t": "名词", "m": "sự xung đột, sự tranh chấp", "coll": "解决争端、避免争端", "s": "双方同意继续对话通过协商寻找解决争端的办法。"}];
const CHUNKS=[["这块玉", "质地细腻", "经过打磨以后", "显得更加温润。"], ["收到对方的询问以后，", "她", "认真核实情况", "及时作出了答复。"], ["他", "担心自己的话会得罪别人", "于是", "先说明了提出建议的原因。"], ["故事中的大臣", "向国王进言", "希望他", "重新考虑这个决定。"], ["发现问题以后，", "团队", "立即商量对策", "尽量减少对后续工作的影响。"], ["他", "提议先核实资料", "再根据实际情况", "决定下一步的安排。"], ["遇到不理解的问题，", "她", "会主动向老师请教", "而不是随意猜测。"], ["这支队伍", "通过长期训练", "不断增强实力", "在比赛中取得了进步。"], ["这位老人", "十分慷慨", "常常拿出自己的积蓄", "帮助有需要的人。"], ["这些年来，", "他", "从未亏待合作伙伴", "始终按照约定支付报酬。"], ["确认车票以后，", "他们", "准备动身", "前往下一座城市。"], ["双方", "经过多轮磋商", "终于", "就合作方式达成了一致。"], ["能够参与这次交流活动", "她", "深感荣幸", "也认真做好了准备。"], ["请你", "替我转达问候", "并告诉老师", "我们都很想念他。"], ["这本书", "图文精美", "孩子一拿到手", "便爱不释手。"], ["故事中的人物", "没有核实对方的身份", "结果", "落入了事先设好的圈套。"], ["借用这些资料以后，", "请", "按照约定的时间", "及时归还。"], ["面对突然提出的问题，", "她", "仍然从容应对", "清楚地说明了自己的观点。"], ["大厅中央", "摆放着一张长桌", "上面", "陈列着这次展览的介绍资料。"], ["作出承诺以后，", "就应该认真兑现", "而不能", "只停留在口头上。"], ["如果只等待机会", "却不愿付出努力", "所谓的计划", "可能只是一种妄想。"], ["他", "发誓要改正自己的错误", "但大家", "更希望看到实际行动。"], ["这部侦探小说", "从河边发现一具尸体开始", "逐步展开", "对事件真相的调查。"], ["做错事情以后，", "不应该撒谎掩盖，", "而应该", "诚实说明情况并承担责任。"], ["庆祝活动", "在广场上隆重举行", "许多居民", "都前来参加。"], ["开幕仪式结束以后，", "来宾们", "依次进入展厅", "参观本次展出的作品。"], ["清晨，", "院子里的花草", "沐浴着阳光", "叶片上还留着细小的水珠。"], ["这家餐厅", "既提供荤菜", "也准备了素食", "方便不同需求的客人选择。"], ["纪念仪式上，", "人们", "神情庄严", "安静地听着主持人的介绍。"], ["工作人员", "已经解释清楚规则", "对方，", "却仍然无理取闹。"], ["讨论不同习俗时，", "应当注意表达方式", "避免因为不了解", "而冒犯他人。"], ["面对未经证实的说法，", "我们，", "不应人云亦云，", "而要先核实事实。"], ["这本游记", "记录了作者", "在边境地区", "走访不同村庄的见闻。"], ["分享照片以前，", "请先检查内容", "避免无意中", "泄露他人的隐私。"], ["她", "率领团队", "经过反复试验", "终于解决了关键问题。"], ["面对突发情况，", "负责人", "保持镇静", "有条不紊地安排相关工作。"], ["这家机构", "不仅资金雄厚", "也十分重视", "专业人才的培养。"], ["他", "做事一贯认真", "即使是很小的细节", "也会仔细核对。"], ["他", "不再用霸道的态度", "要求别人接受意见，", "而是学会了耐心倾听。"], ["这家老店", "凭借可靠的品质", "在顾客中", "赢得了良好的声誉。"], ["为了说明自己的观点，", "她", "列举了几个事例", "并解释其中的联系。"], ["接受这项工作，", "就意味着", "需要认真履行职责", "不能随意推卸责任。"], ["转述别人的观点时，", "应该尊重原意", "不要", "为了支持自己而歪曲事实。"], ["他", "掌握了充分的证据，", "因此", "能够理直气壮地说明自己的理由。"], ["这部作品", "描写了普通人", "面对压迫时", "坚持争取尊严的经历。"], ["除了口头说明，", "工作人员", "还提供了文字材料", "方便大家随时查阅。"], ["出门以前，", "他", "从桌上拿起一副眼镜", "小心地放进包里。"], ["双方", "都表现出愿意合作的姿态", "希望", "通过交流解决分歧。"], ["真诚的交流", "能够帮助人们", "逐渐消除隔阂", "增进彼此的理解。"], ["双方", "同意继续对话", "通过协商", "寻找解决争端的办法。"]];
'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk6-bai27-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===4?WORDS.length:g*10+10);
const groupOf=id=>Math.min(4,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/50 个词语。学完5组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),50)}<div class="ntc-progressgroups">${[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共50个词语，点击 ↗ 学习该词语',totalLearned()+'/50 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为五组：10、10、10、10、7个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===49;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<49){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:4,idx:9};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课50个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课50个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(51px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"2": [0, 3, 22], "5": [0, 3, 22], "8": [0, 3, 22], "11": [0, 3, 22], "14": [1, 5, 6], "17": [1, 5, 6], "20": [1, 5, 6], "23": [1, 5, 6], "26": [1, 5, 6], "29": [0, 3, 22], "32": [0, 3, 22], "35": [0, 3, 22], "38": [1, 5, 6], "41": [0, 3, 22], "44": [0, 3, 22], "47": [1, 5, 6]};
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的50个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第27课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第27课学习进度','第27课 · 50个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 50</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0, 1, 2, 3, 4].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK6 · 第27课';$('ntc-bookmark').textContent=student?total+'/50 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0, 1, 2, 3, 4].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0, 1, 2, 3, 4].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第27课学习进度</div><div style="padding:0 10px">'+total+'/50 个已学词语'+meter(total,50)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
const AUDIO_INDEX={"玉":"data:audio/mpeg;base64,","这块玉质地细腻经过打磨以后显得更加温润。":"data:audio/mpeg;base64,","答复":"data:audio/mpeg;base64,","收到对方的询问以后，她认真核实情况及时作出了答复。":"data:audio/mpeg;base64,","得罪":"data:audio/mpeg;base64,","他担心自己的话会得罪别人于是先说明了提出建议的原因。":"data:audio/mpeg;base64,","大臣":"data:audio/mpeg;base64,","故事中的大臣向国王进言希望他重新考虑这个决定。":"data:audio/mpeg;base64,","对策":"data:audio/mpeg;base64,","发现问题以后，团队立即商量对策尽量减少对后续工作的影响。":"data:audio/mpeg;base64,","提议":"data:audio/mpeg;base64,","他提议先核实资料再根据实际情况决定下一步的安排。":"data:audio/mpeg;base64,","请教":"data:audio/mpeg;base64,","遇到不理解的问题，她会主动向老师请教而不是随意猜测。":"data:audio/mpeg;base64,","实力":"data:audio/mpeg;base64,","这支队伍通过长期训练不断增强实力在比赛中取得了进步。":"data:audio/mpeg;base64,","慷慨":"data:audio/mpeg;base64,","这位老人十分慷慨常常拿出自己的积蓄帮助有需要的人。":"data:audio/mpeg;base64,","亏待":"data:audio/mpeg;base64,","这些年来，他从未亏待合作伙伴始终按照约定支付报酬。":"data:audio/mpeg;base64,","动身":"data:audio/mpeg;base64,","确认车票以后，他们准备动身前往下一座城市。":"data:audio/mpeg;base64,","磋商":"data:audio/mpeg;base64,","双方经过多轮磋商终于就合作方式达成了一致。":"data:audio/mpeg;base64,","荣幸":"data:audio/mpeg;base64,","能够参与这次交流活动她深感荣幸也认真做好了准备。":"data:audio/mpeg;base64,","转达":"data:audio/mpeg;base64,","请你替我转达问候并告诉老师我们都很想念他。":"data:audio/mpeg;base64,","爱不释手":"data:audio/mpeg;base64,","这本书图文精美孩子一拿到手便爱不释手。":"data:audio/mpeg;base64,","圈套":"data:audio/mpeg;base64,","故事中的人物没有核实对方的身份结果落入了事先设好的圈套。":"data:audio/mpeg;base64,","归还":"data:audio/mpeg;base64,","借用这些资料以后，请按照约定的时间及时归还。":"data:audio/mpeg;base64,","从容":"data:audio/mpeg;base64,","面对突然提出的问题，她仍然从容应对清楚地说明了自己的观点。":"data:audio/mpeg;base64,","中央":"data:audio/mpeg;base64,","大厅中央摆放着一张长桌上面陈列着这次展览的介绍资料。":"data:audio/mpeg;base64,","兑现":"data:audio/mpeg;base64,","作出承诺以后，就应该认真兑现而不能只停留在口头上。":"data:audio/mpeg;base64,","妄想":"data:audio/mpeg;base64,","如果只等待机会却不愿付出努力所谓的计划可能只是一种妄想。":"data:audio/mpeg;base64,","发誓":"data:audio/mpeg;base64,","他发誓要改正自己的错误但大家更希望看到实际行动。":"data:audio/mpeg;base64,","尸体":"data:audio/mpeg;base64,","这部侦探小说从河边发现一具尸体开始逐步展开对事件真相的调查。":"data:audio/mpeg;base64,","撒谎":"data:audio/mpeg;base64,","做错事情以后，不应该撒谎掩盖，而应该诚实说明情况并承担责任。":"data:audio/mpeg;base64,","隆重":"data:audio/mpeg;base64,","庆祝活动在广场上隆重举行许多居民都前来参加。":"data:audio/mpeg;base64,","仪式":"data:audio/mpeg;base64,","开幕仪式结束以后，来宾们依次进入展厅参观本次展出的作品。":"data:audio/mpeg;base64,","沐浴":"data:audio/mpeg;base64,","清晨，院子里的花草沐浴着阳光叶片上还留着细小的水珠。":"data:audio/mpeg;base64,","荤":"data:audio/mpeg;base64,","这家餐厅既提供荤菜也准备了素食方便不同需求的客人选择。":"data:audio/mpeg;base64,","庄严":"data:audio/mpeg;base64,","纪念仪式上，人们神情庄严安静地听着主持人的介绍。":"data:audio/mpeg;base64,","无理取闹":"data:audio/mpeg;base64,","工作人员已经解释清楚规则对方，却仍然无理取闹。":"data:audio/mpeg;base64,","冒犯":"data:audio/mpeg;base64,","讨论不同习俗时，应当注意表达方式避免因为不了解而冒犯他人。":"data:audio/mpeg;base64,","亦":"data:audio/mpeg;base64,","面对未经证实的说法，我们，不应人云亦云，而要先核实事实。":"data:audio/mpeg;base64,","边境":"data:audio/mpeg;base64,","这本游记记录了作者在边境地区走访不同村庄的见闻。":"data:audio/mpeg;base64,","泄露":"data:audio/mpeg;base64,","分享照片以前，请先检查内容避免无意中泄露他人的隐私。":"data:audio/mpeg;base64,","率领":"data:audio/mpeg;base64,","她率领团队经过反复试验终于解决了关键问题。":"data:audio/mpeg;base64,","镇静":"data:audio/mpeg;base64,","面对突发情况，负责人保持镇静有条不紊地安排相关工作。":"data:audio/mpeg;base64,","雄厚":"data:audio/mpeg;base64,","这家机构不仅资金雄厚也十分重视专业人才的培养。":"data:audio/mpeg;base64,","一贯":"data:audio/mpeg;base64,","他做事一贯认真即使是很小的细节也会仔细核对。":"data:audio/mpeg;base64,","霸道":"data:audio/mpeg;base64,","他不再用霸道的态度要求别人接受意见，而是学会了耐心倾听。":"data:audio/mpeg;base64,","声誉":"data:audio/mpeg;base64,","这家老店凭借可靠的品质在顾客中赢得了良好的声誉。":"data:audio/mpeg;base64,","列举":"data:audio/mpeg;base64,","为了说明自己的观点，她列举了几个事例并解释其中的联系。":"data:audio/mpeg;base64,","履行":"data:audio/mpeg;base64,","接受这项工作，就意味着需要认真履行职责不能随意推卸责任。":"data:audio/mpeg;base64,","歪曲":"data:audio/mpeg;base64,","转述别人的观点时，应该尊重原意不要为了支持自己而歪曲事实。":"data:audio/mpeg;base64,","理直气壮":"data:audio/mpeg;base64,","他掌握了充分的证据，因此能够理直气壮地说明自己的理由。":"data:audio/mpeg;base64,","压迫":"data:audio/mpeg;base64,","这部作品描写了普通人面对压迫时坚持争取尊严的经历。":"data:audio/mpeg;base64,","口头":"data:audio/mpeg;base64,","除了口头说明，工作人员还提供了文字材料方便大家随时查阅。":"data:audio/mpeg;base64,","副":"data:audio/mpeg;base64,","出门以前，他从桌上拿起一副眼镜小心地放进包里。":"data:audio/mpeg;base64,","姿态":"data:audio/mpeg;base64,","双方都表现出愿意合作的姿态希望通过交流解决分歧。":"data:audio/mpeg;base64,","隔阂":"data:audio/mpeg;base64,","真诚的交流能够帮助人们逐渐消除隔阂增进彼此的理解。":"data:audio/mpeg;base64,","争端":"data:audio/mpeg;base64,","双方同意继续对话通过协商寻找解决争端的办法。":"data:audio/mpeg;base64,"};
function backup(){const content=JSON.stringify({format:'ntc-hsk6-bai27-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK6_Bai27_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk6-bai27-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=50)||!p.memory)throw Error();if(!confirm('恢复第27课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<50;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<5&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<50&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK6第27课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

